node --input-type=module <<'EOF'
import assert from 'node:assert/strict';
import {createTransferWorkspace, createProgressFeed} from './src/workspace.js';
let resolve; const pending = new Promise(r => resolve = r);
const shown = [], history = [];
const feed = createProgressFeed({decode:p => p === 'late' ? pending : p});
const ws = createTransferWorkspace({transport:() => {}, onCancel:() => {}, record:() => {}, showQueued:() => {}, recordProgress:x => history.push([x.attemptId,x.frame]), showProgress:x => shown.push([x.attemptId,x.frame])});
const file = {id:'same',progressFeed:feed};
ws.select(file); feed.emit('late'); ws.hide(); ws.select(file); feed.emit('current'); resolve('old'); await Promise.resolve();
assert.deepEqual(history, [[2,'current'],[1,'old']]);
assert.deepEqual(shown, [[2,'current']]);
ws.dispose(); console.log('late completion ownership check passed');
EOF
